export function ComparisonTable({
  heading = "{{heading}}",
  highlightedPlan = "{{highlightedPlan}}",
  highlightLabel = "{{highlightLabel}}",
  accent = "{{accent}}",
  showAnnualNote = {{showAnnualNote}},
}) {
  const plans = ["Starter", "Pro", "Team"];
  const rows = [
    ["Projects", "3", "Unlimited", "Unlimited"],
    ["Seats", "1", "5", "Unlimited"],
    ["Support", "Email", "Priority", "Dedicated"],
  ];
  const headStyle = (plan) => plan === highlightedPlan ? { background: accent, color: "#FAF7F2" } : {};
  return (
    <>
      <table style={{ borderCollapse: "collapse", width: "100%", maxWidth: 480, font: "14px system-ui, sans-serif", color: "#241430", background: "#FAF7F2" }}>
        <caption style={{ textAlign: "left", fontSize: 18, fontWeight: 700, marginBottom: 12 }}>{heading}</caption>
        <thead>
          <tr>
            <th scope="col" style={{ padding: "10px 14px", borderBottom: "1px solid #24143018" }}>Feature</th>
            {plans.map((plan) => (
              <th key={plan} scope="col" style={{ padding: "10px 14px", borderBottom: "1px solid #24143018", textAlign: "center", fontWeight: 700, ...headStyle(plan) }}>{plan}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map(([label, ...cells]) => (
            <tr key={label}>
              <th scope="row" style={{ padding: "10px 14px", borderBottom: "1px solid #24143018", textAlign: "left", fontWeight: 600 }}>{label}</th>
              {cells.map((cell, i) => (
                <td key={i} style={{ padding: "10px 14px", borderBottom: "1px solid #24143018", textAlign: "center",
                  fontWeight: plans[i] === highlightedPlan ? 700 : 400 }}>{cell}</td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
      {showAnnualNote && <p style={{ margin: "10px 0 0", fontSize: 13, color: "#241430aa" }}>{highlightLabel} &middot; billed annually</p>}
    </>
  );
}
